// Cold-store alarm: relay on D10 follows the probe on A1.
// Three high samples in a row raise it, a clearly low sample clears it.

const int PROBE_PIN = A1;
const int ALARM_PIN = 10;
const float RAISE_C = 12.0;
const float CLEAR_C = 8.0;
const int RUN_NEEDED = 3;
const unsigned long SAMPLE_MS = 20;
const unsigned long REPORT_MS = 500;

float lastC = 0.0;
int highRun = 0;
bool alarmOn = false;
unsigned long lastSample = 0;
unsigned long lastReport = 0;

float readCelsius()
{
    int raw = analogRead(PROBE_PIN);
    return (raw * 5000.0 / 1023.0 - 500.0) / 10.0;
}

void setAlarm(bool on)
{
    alarmOn = on;
    digitalWrite(ALARM_PIN, on ? HIGH : LOW);
}

void evaluate(float c)
{
    lastC = c;
    if (c >= RAISE_C)
    {
        if (highRun < RUN_NEEDED)
        {
            highRun++;
        }
        if (highRun >= RUN_NEEDED)
        {
            setAlarm(true);
        }
    }
    else
    {
        highRun = 0;
        if (c <= CLEAR_C)
        {
            setAlarm(false);
        }
    }
}

void report()
{
    Serial.print("cold ");
    Serial.print(lastC, 1);
    Serial.print(" C alarm=");
    Serial.println(alarmOn ? 1 : 0);
}

void setup()
{
    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);
    Serial.begin(9600);
    lastC = readCelsius();
    lastSample = millis();
    lastReport = millis();
}

void loop()
{
    unsigned long now = millis();
    if (now - lastSample >= SAMPLE_MS)
    {
        lastSample = now;
        evaluate(readCelsius());
    }
    if (now - lastReport >= REPORT_MS)
    {
        lastReport = now;
        report();
    }
}

// Lift call panel: buzzer acknowledges a press, a status line shows the
// panel is alive. Buzzer on D11, call button on D5 (pull-up).

const int BUZZER_PIN = 11;
const int BUTTON_PIN = 5;
const unsigned long BUZZ_MS = 300;
const unsigned long SETTLE_MS = 10;
const unsigned long BEAT_MS = 500;

int rawLevel = HIGH;
bool held = false;
unsigned long rawChangedAt = 0;
unsigned long lastBeat = 0;
unsigned int beats = 0;

bool buzzing = false;
unsigned long buzzStartedAt = 0;

void startBuzz()
{
    digitalWrite(BUZZER_PIN, HIGH);
    buzzing = true;
    buzzStartedAt = millis();
}

void serviceBuzz()
{
    if (buzzing && millis() - buzzStartedAt >= BUZZ_MS)
    {
        digitalWrite(BUZZER_PIN, LOW);
        buzzing = false;
    }
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !buzzing)
        {
            startBuzz();
        }
        held = down;
    }
}

void heartbeat()
{
    beats++;
    Serial.print("alive ");
    Serial.println(beats);
}

void setup()
{
    pinMode(BUZZER_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    digitalWrite(BUZZER_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastBeat = millis();
}

void loop()
{
    scanButton();
    serviceBuzz();
    if (millis() - lastBeat >= BEAT_MS)
    {
        lastBeat = millis();
        heartbeat();
    }
}

// Meadow sprinkler zone: one 500 ms burst per start press.
// Valve relay on D10, start button on D6 (pull-up), status over UART.

const int ZONE_PIN = 10;
const int START_PIN = 6;
const unsigned long BURST_MS = 500;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool zoneOpen = false;
bool held = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long closeAt = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openZone()
{
    zoneOpen = true;
    closeAt = millis() + BURST_MS;
    digitalWrite(ZONE_PIN, HIGH);
    bursts++;
}

void closeZone()
{
    zoneOpen = false;
    digitalWrite(ZONE_PIN, LOW);
}

bool closeDue()
{
    return (long)(millis() - closeAt) >= 0;
}

void scanStart()
{
    int level = digitalRead(START_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (rawLevel == LOW)
    {
        if (!held && !zoneOpen && (now - rawChangedAt >= SETTLE_MS))
        {
            openZone();
            held = true;
        }
    }
    else
    {
        held = false;
    }
}

void report()
{
    Serial.print("zone n=");
    Serial.println(bursts);
}

void setup()
{
    pinMode(ZONE_PIN, OUTPUT);
    pinMode(START_PIN, INPUT_PULLUP);
    digitalWrite(ZONE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanStart();
    if (zoneOpen && closeDue())
    {
        closeZone();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Orchard spray controller: one short burst per trigger press.
// Valve relay on D8, trigger button on D2 (pull-up), status over UART.

const int VALVE_PIN = 8;
const int TRIGGER_PIN = 2;
const unsigned long OPEN_MS = 400;
const unsigned long SETTLE_MS = 8;
const unsigned long REPORT_MS = 1000;

bool valveOpen = false;
bool pressed = false;
int rawLevel = HIGH;
unsigned long rawChangedAt = 0;
unsigned long valveDeadline = 0;
unsigned long lastReport = 0;
unsigned int bursts = 0;

void openValve()
{
    valveOpen = true;
    valveDeadline = millis() + OPEN_MS;
    digitalWrite(VALVE_PIN, HIGH);
    bursts++;
}

void closeValve()
{
    valveOpen = false;
    digitalWrite(VALVE_PIN, LOW);
}

bool deadlineReached()
{
    return millis() >= valveDeadline;
}

void scanTrigger()
{
    int level = digitalRead(TRIGGER_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !pressed && !valveOpen)
        {
            openValve();
        }
        pressed = down;
    }
}

void report()
{
    Serial.print("spray n=");
    Serial.print(bursts);
    Serial.print(" open=");
    Serial.println(valveOpen ? 1 : 0);
}

void setup()
{
    pinMode(VALVE_PIN, OUTPUT);
    pinMode(TRIGGER_PIN, INPUT_PULLUP);
    digitalWrite(VALVE_PIN, LOW);
    Serial.begin(9600);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanTrigger();
    if (valveOpen && deadlineReached())
    {
        closeValve();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Stair light: one press lights the stairs for three seconds.
// Relay on D9, push button on D2, mode switch on D3 (both pull-up).

const int LIGHT_PIN = 9;
const int BUTTON_PIN = 2;
const int MODE_PIN = 3;
const unsigned long LIT_MS = 3000;
const unsigned long SETTLE_MS = 15;
const unsigned long REPORT_MS = 1000;

bool lit = false;
bool held = false;
int rawLevel = HIGH;
int lastMode = HIGH;
unsigned long rawChangedAt = 0;
unsigned long litSince = 0;
unsigned long lastReport = 0;

void armTimer()
{
    litSince = millis();
}

void lightOn()
{
    lit = true;
    armTimer();
    digitalWrite(LIGHT_PIN, HIGH);
}

void lightOff()
{
    lit = false;
    digitalWrite(LIGHT_PIN, LOW);
}

void onModeChange(int mode)
{
    lastMode = mode;
}

void scanButton()
{
    int level = digitalRead(BUTTON_PIN);
    unsigned long now = millis();
    if (level != rawLevel)
    {
        rawLevel = level;
        rawChangedAt = now;
    }
    if (now - rawChangedAt >= SETTLE_MS)
    {
        bool down = (rawLevel == LOW);
        if (down && !held && !lit)
        {
            lightOn();
        }
        held = down;
    }
}

void report()
{
    Serial.print("stair mode=");
    Serial.print(lastMode == HIGH ? 1 : 0);
    Serial.print(" lit=");
    Serial.println(lit ? 1 : 0);
}

void setup()
{
    pinMode(LIGHT_PIN, OUTPUT);
    pinMode(BUTTON_PIN, INPUT_PULLUP);
    pinMode(MODE_PIN, INPUT_PULLUP);
    digitalWrite(LIGHT_PIN, LOW);
    Serial.begin(9600);
    lastMode = digitalRead(MODE_PIN);
    rawChangedAt = millis();
    lastReport = millis();
}

void loop()
{
    scanButton();
    int mode = digitalRead(MODE_PIN);
    if (mode != lastMode)
    {
        onModeChange(mode);
    }
    if (lit && millis() - litSince >= LIT_MS)
    {
        lightOff();
    }
    if (millis() - lastReport >= REPORT_MS)
    {
        lastReport = millis();
        report();
    }
}

// Tank mixer scheduler: 2 s of mixing in every 5 s cycle.
// Relay on D6, hold switch on D3 (pull-up).

const int MIXER_PIN = 6;
const int HOLD_PIN = 3;
const uint16_t RUN_MS = 2000;
const uint16_t CYCLE_MS = 5000;
const uint16_t HOLD_CONFIRM_MS = 200;

uint32_t nextRunAt = 0;
uint32_t stopRunAt = 0;
bool running = false;
unsigned int runCount = 0;

bool holdRaw = false;
bool holdStable = false;
uint32_t holdChangedAt = 0;

uint32_t tickNow()
{
    return millis();
}

void announceRun()
{
    Serial.print("mix ");
    Serial.println(runCount);
}

void startRun(uint32_t now)
{
    running = true;
    runCount++;
    stopRunAt = now + RUN_MS;
    nextRunAt = now + CYCLE_MS;
    announceRun();
}

void stopRun()
{
    running = false;
}

bool held()
{
    return holdStable;
}

void updateHold(uint32_t now)
{
    bool raw = (digitalRead(HOLD_PIN) == LOW);
    if (raw != holdRaw)
    {
        holdRaw = raw;
        holdChangedAt = now;
    }
    if (holdRaw != holdStable && (uint32_t)(now - holdChangedAt) >= HOLD_CONFIRM_MS)
    {
        holdStable = holdRaw;
    }
}

void drive()
{
    bool on = running && !held();
    digitalWrite(MIXER_PIN, on ? HIGH : LOW);
}

void setup()
{
    pinMode(MIXER_PIN, OUTPUT);
    pinMode(HOLD_PIN, INPUT_PULLUP);
    digitalWrite(MIXER_PIN, LOW);
    Serial.begin(9600);
    uint32_t now = tickNow();
    holdRaw = (digitalRead(HOLD_PIN) == LOW);
    holdStable = holdRaw;
    holdChangedAt = now;
    nextRunAt = now + CYCLE_MS;
}

void loop()
{
    uint32_t now = tickNow();
    updateHold(now);
    if (running)
    {
        if ((int32_t)(now - stopRunAt) >= 0)
        {
            stopRun();
        }
    }
    else if ((int32_t)(now - nextRunAt) >= 0)
    {
        startRun(now);
    }
    drive();
}
